#!/usr/bin/env python3
"""Verify Lean 4 proofs generated by generate_answers.py using the Lean REPL.

For each item in the input file (JSON array or JSONL), the script:
  1. Extracts the common header from `autoformalization` (everything before
     the theorem/def/lemma line).
  2. For each answer, extracts the largest ```lean4``` or ```lean``` code block.
  3. Strips header lines (import, open, set_option, etc.) from the extracted
     block so they don't clash with the common header.
  4. Sends `common_header + body` to the Lean REPL and checks for errors/sorries.
  5. Outputs one JSONL line per item with pass/fail per answer.

REPL interaction is modeled after verify_grind_replace.py's InteractiveThread.
"""
import threading, pexpect, json, os, re, argparse, time, sys


# ── Lean REPL interaction (copied from verify_grind_replace.py) ──────────

# Interactive thread class
class InteractiveThread(threading.Thread):
    def __init__(self, session_id, repl_path, lean_env_path, initial_context=None, 
                 timeout=600, expect_timeout=120):
        super().__init__()
        self.session_id = session_id
        self.repl_path = repl_path
        self.lean_env_path = lean_env_path
        self.context = initial_context
        self.session = None
        self.expect_timeout = expect_timeout
        
        self.cmd_response_condition = threading.Event()
        self.cmd_query_condition = threading.Event()
        self.init_complete = threading.Event()
        self.response = None

        self.stop_flag = False
        self.timer = threading.Timer(timeout, self.stop) 

    def initialize_check(self):
        try:
            if self.context == None:
                initialize_check = {"cmd": "def init_check : Nat := 42"}
                self.send_cmd(initialize_check)
            self.session.expect('"env": 0}\r\n\r\n', timeout=self.expect_timeout) 
            self.init_complete.set()
        except:
            self.init_complete.set()
            print(f"Session {self.session_id}: Failed to initialize Lean REPL")
            print(self.context)
            print(self.session.before)
            self.stop()

    def send_cmd(self, cmd):
        cmd_str = json.dumps(cmd, ensure_ascii=False)
        self.session.sendline(cmd_str + '\n')

    def submit_and_receive(self, cmd):
        if self.stop_flag:
            return None

        self.init_complete.wait()
        
        self.send_cmd(cmd)
        
        self.cmd_query_condition.set()

        self.cmd_response_condition.wait() 
        self.cmd_response_condition.clear()
        if self.response:
            output = self.response
            self.response = None
            return output  
        return None

    def process_responses(self):
        while not self.stop_flag:
            self.cmd_query_condition.wait()
            self.cmd_query_condition.clear()

            if self.stop_flag:
                break

            try:
                self.session.expect('\r\n\r\n', timeout=self.expect_timeout) 
                self.session.expect(['\r\n\r\n', pexpect.EOF], timeout=self.expect_timeout)
                output = self.session.before.strip()
                output_dict = json.loads(output)
                self.response = output_dict
                self.cmd_response_condition.set()  

            # prevent deadlocks
            except pexpect.TIMEOUT:
                print("Output timeout")
                self.cmd_response_condition.set()
                break
            except pexpect.EOF:
                print("Session ended unexpectedly.")
                self.cmd_response_condition.set()
                break
            except json.JSONDecodeError as e:
                self.cmd_response_condition.set() 
                print(output)
                break

            except Exception as e:
                print(f"Error in process_responses: {e}")
                self.cmd_response_condition.set()
                break

    def remove_last_comment(self):
        pattern = r'/--[^/]*?-/(\n*)$'
        self.context = re.sub(pattern, '', self.context, flags=re.DOTALL)

    def run(self):
        self.timer.start() 
        try:
            self.session = pexpect.spawn('bash', encoding='utf-8', cwd=self.lean_env_path)
            command = f'lake env {self.repl_path}/.lake/build/bin/repl'
            self.session.sendline(command)
            if self.context != None:
                self.remove_last_comment()
                self.send_cmd({"cmd": self.context})
            self.initialize_check()
            self.process_responses()
            self.stop()
    
        except Exception as e:
            print(f"Session {self.session_id}: An error occurred: {e}")
            self.init_complete.set()  
            self.stop()

    def stop(self):
        self.stop_flag = True
        self.init_complete.set()
        self.cmd_query_condition.set() 
        self.cmd_response_condition.set()
        self.timer.cancel()
        # Terminate the session
        if hasattr(self, 'session') and self.session:
            try:
                self.session.close(force=True)
                del self.session 
            except:
                pass


def start_repl(rp, lep, init_to=300, cmd_to=60, max_retries=3):
    for attempt in range(1, max_retries + 1):
        r = InteractiveThread(
            session_id=f"verify-gen-{attempt}",
            repl_path=rp,
            lean_env_path=lep,
            initial_context="import Mathlib",
            timeout=1800,
            expect_timeout=init_to,
        )
        r.start(); r.init_complete.wait()
        if not r.stop_flag:
            r.expect_timeout = cmd_to  # use shorter timeout for commands
            return r
        r.stop(); r.join()
        if attempt < max_retries:
            wait = 2 ** attempt
            print(f"  REPL init failed (attempt {attempt}/{max_retries}), "
                  f"retrying in {wait}s...", flush=True)
            time.sleep(wait)
        else:
            print(f"  REPL init failed after {max_retries} attempts", flush=True)
    return None


def check_proof(repl, cmd):
    """Send cmd to REPL and return (ok: bool, detail: str)."""
    out = repl.submit_and_receive({"cmd": cmd, "env": 0})
    if out is None: return False, "timeout"
    err = any(m.get("severity") == "error" for m in out.get("messages", []))
    sorry = 'sorries' in out
    msgs = [m.get("data", "")[:120] for m in out.get("messages", []) if m.get("severity") == "error"]
    if err or sorry:
        return False, "; ".join(msgs[:3]) if msgs else "sorries"
    return True, "ok"


# ── Lean block extraction and header stripping ───────────────────────────

def extract_largest_lean_block(text):
    """Extract the largest ```lean4``` or ```lean``` fenced code block."""
    blocks = re.findall(r'```(?:lean4?)\n(.*?)```', text, re.DOTALL)
    if not blocks:
        return None
    return max(blocks, key=len)


# Lines matching these patterns are considered "header" and will be stripped.
_HEADER_RE = re.compile(
    r'^(?:import\s|open\s|set_option\s|section\s|namespace\s|#|/-)',
    re.MULTILINE
)


def extract_common_header(autoformalization):
    """Extract the common header from autoformalization text.
    
    Returns everything before the first theorem/def/lemma/example line,
    with import/open/set_option lines stripped (the REPL already imports
    Mathlib during initialization).
    """
    lines = autoformalization.split('\n')
    header_lines = []
    for line in lines:
        if re.match(r'^(theorem|def|lemma|example)\s', line.strip()):
            break
        header_lines.append(line)
    # Strip import/open/set_option — already handled by REPL init
    filtered = [l for l in header_lines
                if l.strip() and not _HEADER_RE.match(l.strip())]
    return '\n'.join(filtered).strip()


def strip_header(lean_code):
    """Remove header lines (import, open, set_option, etc.) from lean code.
    
    Strips leading lines that are blank, comments, or header directives,
    stopping at the first theorem/def/lemma/example or non-header content.
    """
    lines = lean_code.split('\n')
    start = 0
    for i, line in enumerate(lines):
        stripped = line.strip()
        if not stripped:
            start = i + 1
            continue
        if _HEADER_RE.match(stripped):
            start = i + 1
            continue
        # Multi-line block comment: skip until -/
        if stripped.startswith('/-'):
            # Find end of block comment
            j = i
            while j < len(lines) and '-/' not in lines[j][lines[j].find('/-')+2 if '/-' in lines[j] else 0:]:
                j += 1
            start = j + 1
            continue
        break
    return '\n'.join(lines[start:])


# ── Main processing ──────────────────────────────────────────────────────


def main():
    p = argparse.ArgumentParser(
        description="Verify Lean proofs from generate_answers.py output")
    p.add_argument("--input", required=True,
                    help="Input file (JSON array or JSONL from generate_answers.py)")
    p.add_argument("--output", default="data/verify_gen_results.jsonl",
                    help="Output JSONL file with verification results")
    p.add_argument("--repl_path", required=True,
                    help="Path to the Lean REPL project")
    p.add_argument("--lean_env_path", required=True,
                    help="Path to the Lean/Mathlib environment")
    p.add_argument("--init_timeout", type=int, default=600,
                    help="REPL init timeout in seconds")
    p.add_argument("--cmd_timeout", type=int, default=60,
                    help="Per-command REPL timeout in seconds")
    p.add_argument("--debug_log", default="data/verify_gen_debug.log",
                    help="Path for debug log")
    p.add_argument("--limit", type=int, default=0,
                    help="Limit number of items to process (0 = all)")
    a = p.parse_args()

    a.repl_path = os.path.abspath(a.repl_path)
    a.lean_env_path = os.path.abspath(a.lean_env_path)

    # Read input (JSON array or JSONL)
    print(f"Reading input from {a.input}...", flush=True)
    if a.input.endswith('.jsonl'):
        items = []
        with open(a.input) as f:
            for line in f:
                if line.strip():
                    items.append(json.loads(line))
    else:
        with open(a.input) as f:
            items = json.load(f)

    # Resume: load already-done item indices
    done = set()
    if os.path.exists(a.output):
        with open(a.output) as f:
            for line in f:
                try:
                    done.add(json.loads(line)["item_idx"])
                except:
                    pass

    # Add item_idx if not present
    for i, item in enumerate(items):
        item.setdefault("_item_idx", i)
    items = [item for item in items if item["_item_idx"] not in done]

    if a.limit > 0:
        items = items[:a.limit]

    total_answers = sum(len(it.get("answers", [])) for it in items)
    print(f"Processing {len(items)} items ({total_answers} total answers), "
          f"done={len(done)}", flush=True)

    outf = open(a.output, "a")
    g_stats = {"items": 0, "total_pass": 0, "total_fail": 0,
               "total_skip": 0, "items_with_pass": 0}

    # Start a single REPL session
    print("\n--- Starting REPL session ---", flush=True)
    repl = start_repl(a.repl_path, a.lean_env_path,
                      a.init_timeout, a.cmd_timeout)
    if repl is None:
        print("REPL init failed! Aborting.", flush=True)
        for item in items:
            outf.write(json.dumps({
                "item_idx": item["_item_idx"],
                "error": "init_failed",
                "n_answers": len(item.get("answers", [])),
                "n_pass": 0, "n_fail": 0, "n_skip": 0,
                "answers": [],
            }) + '\n')
        outf.flush()
        outf.close()
        return

    # Flatten into individual (item, ans_idx) work units so each proof
    # is independent and REPL restarts don't skip remaining answers.
    work = []
    # Track expected answer count per item for incremental flushing
    item_answer_count = {}  # item_idx -> total answers expected
    for item in items:
        item_idx = item["_item_idx"]
        common_header = extract_common_header(item.get("autoformalization", ""))
        answers = item.get("answers", [])
        item_answer_count[item_idx] = len(answers)
        for ans_idx, answer in enumerate(answers):
            work.append({
                "item_idx": item_idx,
                "ans_idx": ans_idx,
                "answer": answer,
                "common_header": common_header,
                "item": item,
            })

    # Build item lookup for incremental flushing
    item_by_idx = {item["_item_idx"]: item for item in items}

    def _flush_completed_items(answer_results, flushed_items, outf, g_stats):
        """Write completed items (all answers processed) to output JSONL."""
        newly_flushed = 0
        for item_idx in list(answer_results.keys()):
            if item_idx in flushed_items:
                continue
            expected = item_answer_count.get(item_idx, 0)
            results = answer_results[item_idx]
            if len(results) < expected:
                continue  # not all answers processed yet

            item = item_by_idx[item_idx]
            answers = item.get("answers", [])
            n_pass = sum(1 for r in results if r["pass"])
            n_fail = sum(1 for r in results if not r["pass"]
                         and r["detail"] not in ("no_lean_block", "empty_body"))
            n_skip = sum(1 for r in results
                         if r["detail"] in ("no_lean_block", "empty_body"))

            g_stats["items"] += 1
            g_stats["total_pass"] += n_pass
            g_stats["total_fail"] += n_fail
            g_stats["total_skip"] += n_skip
            if n_pass > 0:
                g_stats["items_with_pass"] += 1

            pass_rate = round(n_pass / len(answers) * 100, 2) if answers else 0
            result = {
                "item_idx": item_idx,
                "source": item.get("source", ""),
                "theorem_names": item.get("theorem_names", []),
                "n_answers": len(answers),
                "n_pass": n_pass,
                "n_fail": n_fail,
                "n_skip": n_skip,
                "pass_rate": pass_rate,
                "answers": results,
            }
            outf.write(json.dumps(result, ensure_ascii=False) + '\n')
            flushed_items.add(item_idx)
            newly_flushed += 1

            item_pass_rate = (g_stats["items_with_pass"] / g_stats["items"] * 100
                              if g_stats["items"] else 0)
            print(f"  [{g_stats['items']}/{len(items)}] "
                  f"item_idx={item_idx} "
                  f"pass={n_pass}/{len(answers)} "
                  f"({pass_rate:.0f}%) "
                  f"| overall: {g_stats['items_with_pass']}/{g_stats['items']} "
                  f"items pass ({item_pass_rate:.0f}%)",
                  flush=True)

        if newly_flushed > 0:
            outf.flush()
        return newly_flushed

    # Process each proof independently
    answer_results = {}  # item_idx -> list of per-answer results
    flushed_items = set()  # item indices already written to output
    wi = 0
    while wi < len(work):
        w = work[wi]

        # Restart REPL if it died
        if repl.stop_flag:
            repl.stop(); repl.join()
            remaining = len(work) - wi
            print(f"  Session died, restarting for {remaining} "
                  f"remaining proofs...", flush=True)
            repl = start_repl(a.repl_path, a.lean_env_path,
                              a.init_timeout, a.cmd_timeout)
            if repl is None:
                print("  REPL restart failed, marking remaining as failed",
                      flush=True)
                for rw in work[wi:]:
                    answer_results.setdefault(rw["item_idx"], []).append({
                        "answer_idx": rw["ans_idx"],
                        "pass": False,
                        "detail": "restart_failed",
                    })
                break
            continue  # retry same proof with new session

        item_idx = w["item_idx"]
        ans_idx = w["ans_idx"]
        answer = w["answer"]
        common_header = w["common_header"]

        lean_block = extract_largest_lean_block(answer)
        if lean_block is None:
            print(f"    [item {item_idx} ans {ans_idx}] NO lean block found",
                  flush=True)
            answer_results.setdefault(item_idx, []).append({
                "answer_idx": ans_idx, "pass": False, "detail": "no_lean_block",
            })
            wi += 1
            # Flush every 20 work units
            if wi % 20 == 0:
                _flush_completed_items(answer_results, flushed_items, outf, g_stats)
            continue

        body = strip_header(lean_block)
        if not body.strip():
            print(f"    [item {item_idx} ans {ans_idx}] Empty body after "
                  f"stripping header", flush=True)
            answer_results.setdefault(item_idx, []).append({
                "answer_idx": ans_idx, "pass": False, "detail": "empty_body",
            })
            wi += 1
            # Flush every 20 work units
            if wi % 20 == 0:
                _flush_completed_items(answer_results, flushed_items, outf, g_stats)
            continue

        full_cmd = common_header + '\n' + body if common_header else body

        # Debug: show extracted proof
        preview = full_cmd[:300].replace('\n', '\n      ')
        print(f"    [item {item_idx} ans {ans_idx}] "
              f"lean_block={len(lean_block)}ch body={len(body)}ch "
              f"cmd={len(full_cmd)}ch", flush=True)
        print(f"      {preview}{'...' if len(full_cmd) > 300 else ''}",
              flush=True)

        t0 = time.time()
        ok, detail = check_proof(repl, full_cmd)
        elapsed = round(time.time() - t0, 3)

        print(f"    [item {item_idx} ans {ans_idx}] "
              f"→ {'PASS' if ok else 'FAIL'} ({elapsed}s) {detail[:80]}",
              flush=True)

        answer_results.setdefault(item_idx, []).append({
            "answer_idx": ans_idx,
            "pass": ok,
            "detail": detail,
            "elapsed_s": elapsed,
        })
        wi += 1

        # Flush completed items to disk every 20 work units
        if wi % 20 == 0:
            _flush_completed_items(answer_results, flushed_items, outf, g_stats)

    if repl and not repl.stop_flag:
        repl.stop()
        repl.join()

    # Final flush: write any remaining completed items
    _flush_completed_items(answer_results, flushed_items, outf, g_stats)
    outf.close()

    total_checked = g_stats["total_pass"] + g_stats["total_fail"]
    overall_pass = (g_stats["total_pass"] / total_checked * 100
                    if total_checked else 0)
    item_pass = (g_stats["items_with_pass"] / g_stats["items"] * 100
                 if g_stats["items"] else 0)
    print(f"\n{'='*60}", flush=True)
    print(f"VERIFICATION RESULTS", flush=True)
    print(f"{'='*60}", flush=True)
    print(f"Items processed:       {g_stats['items']}", flush=True)
    print(f"Answers passed:        {g_stats['total_pass']}/{total_checked} "
          f"({overall_pass:.1f}%)", flush=True)
    print(f"Answers skipped:       {g_stats['total_skip']}", flush=True)
    print(f"Items with ≥1 pass:    {g_stats['items_with_pass']} "
          f"({item_pass:.1f}%)", flush=True)


if __name__ == "__main__":
    main()
